    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    output = [row[:] for row in grid]

    # Find horizontal lines (complete rows of one value)
    horizontal_lines = []
    for r in range(rows):
        if all(grid[r][c] == grid[r][0] for c in range(cols)):
            horizontal_lines.append(r)

    # Find vertical lines (complete columns of one value)
    vertical_lines = []
    for c in range(cols):
        if all(grid[r][c] == grid[0][c] for r in range(rows)):
            vertical_lines.append(c)

    # Reflect non-line values across all lines
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == 3:
