            for h in horizontal_lines:
                new_r = 2 * h - r
                if 0 <= new_r < rows:
                    output[new_r][c] = val

            for v in vertical_lines:
                new_c = 2 * v - c
                if 0 <= new_c < cols:
                    output[r][new_c] = val

