def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if rows == 0 or cols == 0:
        return [row[:] for row in grid]

    # Find the background color (most frequent)
    from collections import Counter
    colors = []
    for r in range(rows):
        for c in range(cols):
            colors.append(grid[r][c])
    bg = max(Counter(colors).keys(), key=lambda x: Counter(colors)[x])

    # Find horizontal lines (complete rows of same non-bg color)
    horizontal_lines = []
    for r in range(rows):
        if all(grid[r][c] == grid[r][0] for c in range(cols)):
            horizontal_lines.append(r)

    # Find vertical lines (complete columns of same non-bg color)
    vertical_lines = []
    for c in range(cols):
        if all(grid[r][c] == grid[0][c] for r in range(rows)):
            vertical_lines.append(c)

    # Start with copy of input
    output = [row[:] for row in grid]

    # Collect all non-background cells (the objects)
    objects = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg:
                objects.append((r, c, grid[r][c]))

    # Reflect objects across all horizontal and vertical lines
    for (r, c, val) in objects:
        for h in horizontal_lines:
            new_r = 2 * h - r
            if 0 <= new_r < rows and new_r != r:
                output[new_r][c] = val

        for v in vertical_lines:
            new_c = 2 * v - c
            if 0 <= new_c < cols and new_c != c:
                output[r][new_c] = val

    # Lines always stay and don't get overwritten
    for r in horizontal_lines:
        for c in range(cols):
            if grid[r][c] != bg:
                output[r][c] = grid[r][c]

    return output
