def transform(grid):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    output = [row[:] for row in grid]

    # Find horizontal axis line (row of all same non-background value)
    for ar in range(rows):
        val = grid[ar][0]
        if val == 2 or val == 3:
            if all(grid[ar][c] == val for c in range(cols)):
                axis_row = ar
                break
    else:
        return output

    # Count rows above and below axis
    above = axis_row  # rows 0 to axis_row-1
    below = rows - 1 - axis_row  # rows axis_row+1 to end

    # Reflect: top section gets bottom section, bottom gets top
    for i in range(above):
        src = axis_row + 1 + i
        if src < rows:
            output[i] = [grid[src][j] for j in range(cols)]

    for i in range(below):
        src = axis_row - 1 - i
        if src >= 0:
            output[axis_row + 1 + i] = [grid[src][j] for j in range(cols)]

    return output
